<script setup>
import { wineTypes, suggestPlacement } from '~/utils/placement'
import { currencies, purchasePayload } from '~/utils/purchases'
import { normalizeBarcode } from '~/utils/barcode'
const props=defineProps({cellar:Object}),emit=defineEmits(['close','imported'])
const inventory=ref(props.cellar),rows=ref([]),busy=ref(false),error=ref(''),filename=ref('')
const columns='name,vintage,region,type,quantity,rack,slot,barcode,price,currency,purchase_date,seller\n'
function download(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function template(){download(new Blob([columns],{type:'text/csv;charset=utf-8'}),'winevault-template.csv')}
async function exportCollection(){busy.value=true;error.value='';try{const blob=await $fetch('/api/collection/export',{responseType:'blob'});download(blob,'winevault-collection.csv')}catch(e){error.value=typeof e.data==='string'?e.data:'Could not export the collection.'}finally{busy.value=false}}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>2*1024*1024){error.value='Choose a CSV smaller than 2 MB.';return}busy.value=true;error.value='';rows.value=[];try{const text=await file.text();inventory.value=await $fetch('/api/cellar');const preview=await $fetch('/api/collection/import/preview',{method:'POST',body:text,headers:{'Content-Type':'text/csv'},retry:0});filename.value=file.name;rows.value=preview.rows.map(row=>{const exact=inventory.value.racks.find(r=>r.id===row.bottle.rack),named=inventory.value.racks.filter(r=>r.name===row.bottle.rack);return {...row.bottle,sourceRow:row.row,vintage:row.vintageText,quantity:row.quantity,rack:exact?.id||(named.length===1?named[0].id:row.bottle.rack),slotAddress:row.slotAddress,price:row.price,currency:row.bottle.currency||'CHF',warnings:row.errors}})}catch(e){error.value=typeof e.data==='string'?e.data:'Could not read CSV. Use the template and check the file.'}finally{busy.value=false}}
const address=(rack,slot)=>`${String.fromCharCode(65+slot%rack.columns)}${Math.floor(slot/rack.columns)+1}`
const review=computed(()=>{
 const bottles=[...inventory.value.bottles],results=[];let total=0
 for(const row of rows.value){const issues=[],vintage=String(row.vintage).trim(),year=/^(NV|0)$/i.test(vintage)?0:Number(vintage)
  if(!row.name.trim()||row.name.length>150||!row.region.trim()||row.region.length>200||!wineTypes.includes(row.type)||!vintage||(!/^(NV|0)$/i.test(vintage)&&(!/^\d{4}$/.test(vintage)||year<1900||year>new Date().getFullYear()+1)))issues.push('Check wine name, vintage (year or NV), region, and type.')
  if(!Number.isInteger(row.quantity)||row.quantity<1||row.quantity>400)issues.push('Quantity must be between 1 and 400.')
  const quantity=Number.isInteger(row.quantity)&&row.quantity>0&&row.quantity<=400?row.quantity:1;total+=quantity
  let purchase={};try{purchase=purchasePayload(row)}catch(e){issues.push(e.message)}
  if(purchase.priceMinor!=null&&!currencies.includes(row.currency))issues.push('Choose a supported currency for the price.')
  if(row.purchaseDate){const date=new Date(row.purchaseDate+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(row.purchaseDate)||Number.isNaN(date.getTime())||date.toISOString().slice(0,10)!==row.purchaseDate||Number(row.purchaseDate.slice(0,4))<1900)issues.push('Use a valid purchase date as YYYY-MM-DD.')}
  if(row.seller?.length>200)issues.push('Seller must be at most 200 characters.')
  if(row.barcode&&!normalizeBarcode(row.barcode))issues.push('Check the barcode checksum.')
  const suggestion=suggestPlacement({racks:inventory.value.racks,bottles,preferences:inventory.value.preferences,type:row.type,quantity})
  const rack=inventory.value.racks.find(r=>r.id===(row.rack||suggestion.rack));let slots=[]
  if(!rack)issues.push('Choose an existing shelf.')
  else{const free=Array.from({length:rack.capacity},(_,i)=>i).filter(slot=>!bottles.some(b=>b.rack===rack.id&&b.slot===slot));const requested=String(row.slotAddress||'').trim().toUpperCase()
   if(requested){const match=requested.match(/^([A-T])([1-9]\d*)$/);const slot=match?(Number(match[2])-1)*rack.columns+match[1].charCodeAt(0)-65:-1
    if(!match||match[1].charCodeAt(0)-65>=rack.columns||slot>=rack.capacity||!free.includes(slot))issues.push('The requested starting slot is occupied or outside this shelf. Clear it for automatic placement.')
    else slots=[slot,...free.filter(n=>n!==slot)].slice(0,quantity)
   }else slots=free.slice(0,quantity)
   if(slots.length!==quantity)issues.push('This shelf does not have enough free slots.')
   for(const slot of slots)bottles.push({rack:rack.id,slot})
  }
  results.push({issues,rack,slots,purchase,year})
 }
 return {results,total,valid:rows.value.length>0&&total<=2000&&results.every(row=>!row.issues.length)}
})
async function importCollection(){if(!review.value.valid)return;busy.value=true;error.value='';try{const bottles=rows.value.flatMap((row,i)=>{const plan=review.value.results[i];return plan.slots.map(slot=>({name:row.name.trim(),vintage:plan.year,region:row.region.trim(),type:row.type,rack:plan.rack.id,slot,barcode:row.barcode,...plan.purchase}))});const result=await $fetch('/api/collection/import',{method:'POST',body:{bottles},retry:0});emit('imported',result.imported)}catch(e){error.value=typeof e.data==='string'?e.data:'Could not import bottles. Nothing has been added.';try{inventory.value=await $fetch('/api/cellar')}catch{}}finally{busy.value=false}}
</script>
<template><AppDialog label="CSV import and export" :busy="busy" :wide="true" @close="emit('close')"><button class="close" aria-label="Close CSV transfer" :disabled="busy" @click="emit('close')">×</button><section class="collection-transfer"><h2>Import & export collection</h2><p>Export your current inventory or upload a UTF-8 CSV. Review wine details and shelf placement before adding any bottles.</p><div class="transfer-actions"><button class="editor-secondary" :disabled="busy" @click="exportCollection">Export collection CSV</button><button class="editor-secondary" :disabled="busy" @click="template">Download CSV template</button></div><label>Import CSV file<input type="file" accept=".csv,text/csv" :disabled="busy" @change="upload"></label><p class="csv-help">Required: name, vintage (year or NV), region, type. Optional: quantity, rack (ID or unique shelf name), slot (e.g. A1), barcode, price per bottle, currency, purchase_date (YYYY-MM-DD), seller. Limits: 2 MB, 1,000 rows, 2,000 bottles.</p><p v-if="busy" role="status">Working…</p><p v-if="error" role="alert" class="scanner-error">{{error}}</p><template v-if="rows.length"><h3>Review {{filename}}</h3><p>{{review.total}} bottles · Changes are saved together only when you confirm.</p><p v-if="review.total>2000" role="alert" class="scanner-error">Import at most 2,000 bottles at a time.</p><fieldset :disabled="busy" class="csv-review"><article v-for="(row,i) in rows" :key="row.sourceRow"><header><strong>CSV row {{row.sourceRow}}</strong><button type="button" class="text-button" @click="rows.splice(i,1)">Remove row</button></header><p v-if="row.warnings.length" class="csv-help">CSV notes: {{row.warnings.join(' ')}} Review and correct the fields below.</p><label>Wine name<input v-model="row.name" maxlength="150"></label><div class="form-row"><label>Vintage<input v-model="row.vintage" placeholder="2020 or NV"></label><label>Type<select v-model="row.type" aria-label="Imported wine type"><option value="" disabled>Choose type</option><option v-for="type in wineTypes" :key="type">{{type}}</option></select></label></div><label>Region<input v-model="row.region" maxlength="200"></label><div class="form-row"><label>Quantity<input v-model.number="row.quantity" type="number" min="1" max="400"></label><label>Shelf<select v-model="row.rack" aria-label="Import destination shelf"><option value="">Auto choose</option><option v-if="row.rack&&!inventory.racks.some(r=>r.id===row.rack)" :value="row.rack">Unavailable: {{row.rack}}</option><option v-for="rack in inventory.racks" :key="rack.id" :value="rack.id">{{rack.name}}</option></select></label></div><label>Starting slot (optional)<input v-model="row.slotAddress" placeholder="Automatic, or e.g. A1"></label><p v-if="review.results[i].rack">Placement: {{review.results[i].rack.name}} · {{review.results[i].slots.map(slot=>address(review.results[i].rack,slot)).join(', ')||'No slots available'}}</p><details><summary>Purchase details & barcode</summary><PurchaseFields :draft="row"/><label>Barcode<input v-model="row.barcode" maxlength="20"></label></details><p v-for="issue in review.results[i].issues" :key="issue" class="scanner-error" role="alert">{{issue}}</p></article></fieldset><button class="primary" :disabled="busy||!review.valid" @click="importCollection">{{busy?'Importing…':'Confirm import · '+review.total+' bottles'}}</button></template></section></AppDialog></template>
<style scoped>.collection-transfer{text-align:left}.collection-transfer h2{padding-right:20px}.collection-transfer>p,.csv-review p{font-size:12px;color:#857b70;line-height:1.6;margin:12px 0}.transfer-actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.csv-help{font-size:11px!important}.csv-review{padding:0;border:0;min-width:0}.csv-review article{border:1px solid #e8e0d6;border-radius:8px;padding:16px;margin:16px 0}.csv-review header{display:flex;align-items:center;justify-content:space-between;gap:12px}.csv-review .scanner-error{color:#a53450}.form-row label{min-width:0}details{margin-top:12px}summary{cursor:pointer}.collection-transfer input[type=file]{max-width:100%}</style>
